def transform(grid):
    """Fill punched holes: restore outside color, frame color, and anti-diagonal stripes inside the frame."""
    h,w=len(grid),len(grid[0])
    g=[row[:] for row in grid]
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    outside=grid[0][0]
    fr=fc=frame=None
    for c,n in sorted(cnt.items(), key=lambda kv:-kv[1]):
        if c in (0,outside): continue
        rowsf=[i for i in range(h) if grid[i].count(c)>=w//2]
        colsf=[j for j in range(w) if sum(1 for i in range(h) if grid[i][j]==c)>=h//2]
        if rowsf and colsf: frame=c; fr=rowsf[0]; fc=colsf[0]; break
    for r in range(h):
        for j in range(w):
            if g[r][j]!=0: continue
            if r<fr or j<fc: g[r][j]=outside
            elif r==fr or j==fc: g[r][j]=frame
            else:
                val=None
                for dr in range(1,h):
                    for rr,jj in ((r+dr,j-dr),(r-dr,j+dr)):
                        if fr<rr<h and fc<jj<w and g[rr][jj]!=0:
                            val=g[rr][jj]; break
                    if val is not None: break
                if val is None:
                    for dr in range(1,h):
                        for rr,jj in ((r-dr,j+dr),(r+dr,j-dr)):
                            if 0<=rr<h and 0<=jj<w and g[rr][jj]!=0:
                                val=g[rr][jj]; break
                        if val is not None: break
                g[r][j]=val
    return g
